[Form]
public class LACTutorialQueryBasedReportCode extends FormRun
{
    SRSPrintDestinationSettings destinationSettings;

}

/// <summary>
///
/// </summary>
public void clicked()
{
    LACReportName         reportName = 'LACTutorialQueryBasedReport';
    LACReport             report;
    LACReportOrigin_Query queryOrigin;
    Query                 query;
    QueryBuildDataSource  qbds;
    SysDictClass          dictClass;
    LACValueSource_CustomCode customCode;
    LACArchiveForms       archiveForms;
    LACReportParameter    reportParameter;
    container             rangesMapPack;
    Map                   rangeValuesMap;
    queryBuildRange       qr;
    super();
    report = LACReport::find(reportName);
    if (report.RecId)
    {
        if (Box::yesNo(strFmt('Report \'%1\' already exists. Would you like to delete it and create from scratch automatically?', reportName), DialogButton::Yes, 'Create report') == DialogButton::Yes)
        {
            ttsBegin;
            report = LACReport::find(reportName, true);
            if (report)
            {
                report.delete();
            }
            ttsCommit;
        }
        else
        {
            return;
        }
    }
    // Create report entry
    ttsBegin;
    report.ReportName     = reportName;
    report.OriginType     = LACReportOriginType::Query;
    report.Active         = NoYes::Yes;
    report.Archive        = LACArchiveType::Default;
    report.ArchiveSaveXML = NoYes::Yes;
    report.insert();
    // Build query for report
    query = new Query();
    qbds = query.addDataSource(tableNum(InventTable));
    qbds.name(tableStr(InventTable)); // We want data source names without default _1 postfix

    // Create custom code instance for field list build
    dictClass      = SysDictClass::newName(report.customCodeClass());
    new ExecutePermission().assert();
    customCode = dictClass.makeObject();
    CodeAccessPermission::revertAssert();
    customCode.queryBuildAddField(qbds, fieldStr(InventTable, ItemId));
    customCode.queryBuildAddMethod(qbds, tableMethodStr(InventTable, ItemName));
    // If there is more data sources in query, you may want to specify layout:
    // customCode.queryBuildAddLayout(query, qbdsAnother, LACQueryDSLayout::SameLevel);

    queryOrigin = report.reportOrigin();
    queryOrigin.parmQuerySource(LACQuerySource::Wizard);
    queryOrigin.parmQuery(query);
    queryOrigin.parmFieldListMap(customCode.queryBuildFieldListMap(query));
    queryOrigin.parmDataSourcePropertiesMap(customCode.dataSourcePropertiesMap(query));

    report.setOriginData(queryOrigin);
    report.update();
    ttsCommit;
    LACReport::cacheValueSourcesClear(reportName);
    LACArgsCache argsCache = LACArgsCache::newCache(reportName, report, queryOrigin);
    LACReportLoader::reloadElementsAndStyleSheet(report.ReportName, argsCache);
    // Associating report with form
    archiveForms.ReportName = reportName;
    archiveForms.FormName   = element.name();
    archiveForms.ControlName = '###NotExist###'; // This is not existing control name, this way automatic button will not be created in form
    archiveForms.ControlLocation = LACInsertControlLocation::After;
    archiveForms.SingleButton = NoYes::Yes;
    archiveForms.MultiRunDsName = InventTable_DS.name();
    archiveForms.MultiSelectType = LACMultiSelectType::MultiReport;
    archiveForms.Label = 'MyButton';
    archiveForms.insert();
    LACReport::cacheValueSourcesClear(reportName);
    argsCache = LACArgsCache::newCache(report.ReportName, report, queryOrigin);  // Reinitializing Args cache, so value sources are reloaded, and Forms are included
    // Create dialog fields for execution from this form, if dialog will not be used, you can skip creating dialog fields(LACReportParameter)
    reportParameter.initFromLACReportParameterReference(LACReportParameterReference::newFromRecord(archiveForms));
    reportParameter.ParameterName = 'ItemId';
    reportParameter.Show          = NoYes::Yes;
    reportParameter.LoadInstruction = LACLoadInstruction::Fixed; // We would like it initialize always
    // Build parameter formula
    LACValueBuilder builder = LACValueBuilder::newValue(ReportName, argsCache, 'Forms'); // Forms
    builder.add(element.name(), LACValueSource_Form::construct()); // LACTutorialQueryBasedReport.
    builder.add(InventTable_DS.name(), LACValueSource_FormDataSource::construct()); // InventTable.
    builder.add(fieldStr(InventTable, ItemId)); // ItemId
    // Add formula to expression
    LACExpressionBuilder::newFieldExpr(reportParameter.fieldExpression(argsCache), LACSymbols::ReportParameter_Value).addValue(builder.value());
    reportParameter.insert();

    // Now we can link query ranges with a) parameter or b) caller form data source directly
    // Whenever we execute report, values from caller form data source will be set on dialog field or query range
    query          = new Query(queryOrigin.parmQuery().pack());
    LACQueryGroupByUtils::unpackQueryRanges(query, archiveForms.linkPackage().linkQueryPackRangesAndFilters());
    rangesMapPack  = archiveForms.linkPackage().linkQueryRangesPacked();
    rangeValuesMap = rangesMapPack?Map::create(rangesMapPack):new Map(Types::String, Types::Container);

    qbds = query.dataSourceTable(tableNum(InventTable));
    // a) Adding new query range that takes value from dialog field
    qr = qbds.addRange(fieldNum(InventTable, ItemId));
    // Set formula for query range
    LACSysQueryFormHelper::setRangeFormula(argsCache,
                                           qr, // Setting formula Parameter.ItemId
                                           LACValueBuilder::newValue(reportName, argsCache, 'Parameter').add('ItemId').value(),
                                           rangeValuesMap);
    // Setting range as Locked - as this ensures that range is not editable, and on each execution
    // formula is range formula is recalculated
    LACSysQueryFormHelper::setRangeFormula(argsCache,
                                           qr, // Setting formula Value:1
                                           LACValueBuilder::newValue(reportName, argsCache, 'Value').add('1').value(),
                                           rangeValuesMap,
                                           LACSysQueryFormHelper::fieldLock);



    // b) Alternatively we can get range value not from report parameters (dialog field), but directly from caller form data source
    qr = qbds.addRange(fieldNum(InventTable, ItemId));
    LACValueBuilder valueBuilder = LACValueBuilder::newValue(reportName, argsCache, 'Forms'); // Forms.
    valueBuilder.add(element.name(), LACValueSource_Form::construct()); // LACTutorialQueryBasedReport.
    valueBuilder.add(InventTable_ds.name(), LACValueSource_FormDataSource::construct()); // InventTable.
    valueBuilder.add(fieldStr(InventTable, ItemId)); // ItemId
    // Set formula for query range
    LACSysQueryFormHelper::setRangeFormula(argsCache,
                                           qr, 
                                           valueBuilder.value(), 
                                           rangeValuesMap);

    LACSysQueryFormHelper::setRangeFormula(argsCache,
                                           qr,  // Setting formula Value:1
                                           LACValueBuilder::newValue(reportName, argsCache, 'Value').add('1').value(),
                                           rangeValuesMap,
                                           LACSysQueryFormHelper::fieldLock);


    archiveForms.linkPackage().linkQueryPackRangesAndFilters(LACQueryGroupByUtils::packQueryRanges(query));
    archiveForms.linkPackage().linkQueryRangesPacked(rangeValuesMap.pack());
    ttsBegin;
    archiveForms.update();
    ttsCommit;
    info(strFmt('Report %1 has been created and is ready to be used', reportName));
}

/// <summary>
///
/// </summary>
public void clicked()
{
    LACReportName   reportName = 'LACTutorialQueryBasedReport';
    LACReport       report;
    MenuFunction    menuFunction;
    Args            args;
    LACArgs         lacArgs = LACArgs::construct();

    if (!destinationSettings)
    {
        throw error("@SYS323108");
    }
    report = LACReport::find(reportName);
    if (!report.RecId)
    {
        throw error(strFmt("@LAC560", reportName));
    }
    if (report.OriginType != LACReportOriginType::Query)
    {
        throw error("@LAC927");
    }
    menuFunction = new MenuFunction(menuitemOutputStr(LACRunQueryReport), MenuItemType::Output);
    args = new Args();
    args.parm(reportName);
    args.caller(element); // < This makes report aware what form has called it, and initialize dialog accordingly
    lacArgs.parmReportName(reportName);
    lacArgs.parmSRSPrintDestinationSettings(destinationSettings);
    Args.parmObject(lacArgs);
    //Args.record(InventTable);
    menuFunction.run(args);
}

/// <summary>
///
/// </summary>
public void clicked()
{
    LACReportName   reportName = 'LACTutorialQueryBasedReport';
    LACReport       report;
    MenuFunction    menuFunction;
    Args            args;
    if (!destinationSettings)
    {
        throw error("@SYS323108");
    }
    report = LACReport::find(reportName);
    if (!report.RecId)
    {
        throw error(strFmt("@LAC560", reportName));
    }
    if (report.OriginType != LACReportOriginType::Query)
    {
        throw error("@LAC927");
    }
    menuFunction = new MenuFunction(menuitemOutputStr(LACRunController), MenuItemType::Output);
    args = new Args();
    args.record(LACReport::find(reportName));
    args.parmEnumType(enumNum(SysOperationExecutionMode));
    args.parmEnum(SysOperationExecutionMode::Synchronous);
    args.parm(strFmt('%1.%2',classStr(LACRunQueryService), methodStr(LACRunQueryService, runQuery)));
    // args.caller(element);
    menuFunction.run(args);
}

/// <summary>
///
/// </summary>
public void clicked()
{
    // Run report without contextual information - standalone (Form Links will be skipped)
    LACReportName   reportName = 'LACTutorialQueryBasedReport';
    LACReport       reportRec = LACReport::find(reportName);
    if (!reportRec)
    {
        throw error(strFmt('Report \'%1\' was not found. Click \'Create report\' to create it.', reportName));
    }
    LACRunQueryServiceController runQueryReport = LACRunQueryServiceController::newReport(reportName, LACArgsCache::newCache(reportName), true); // <- True -> load from last values

    // Optional - set query ranges
    Query q = runQueryReport.parmLACRunQueryDataContract().parmQuery();
    QueryBuildDataSource qbds = q.dataSourceTable(tableNum(InventTable));
    qbds.addRange(fieldNum(InventTable, ItemId)).value("123");

    // Optional - where to print
    runQueryReport.parmPrintSettings().unpack(destinationSettings.pack());

    // Optional - Show/Hide dialog
    runQueryReport.parmShowDialog(true);
    runQueryReport.startOperation();
}

/// <summary>
///
/// </summary>
public void clicked()
{
    boolean     fileGenerated;
    // Run report without contextual information - standalone (Form Links will be skipped)
    LACReportName   reportName = 'LACTutorialQueryBasedReport';
    LACReport       reportRec = LACReport::find(reportName);
    if (!reportRec)
    {
        throw error(strFmt('Report \'%1\' was not found. Click \'Create report\' to create it.', reportName));
    }
    LACRunQueryServiceController runQueryReport = LACRunQueryServiceController::newReport(reportName, LACArgsCache::newCache(reportName), true); // <- True -> load from last values

    // Optional - set query ranges
    Query q = runQueryReport.parmLACRunQueryDataContract().parmQuery();
    QueryBuildDataSource qbds = q.dataSourceTable(tableNum(InventTable));
    qbds.addRange(fieldNum(InventTable, ItemId)).value('123');

    // Where to print - Set settings for Sync and non delivery mode
    //SRSPrintDestinationSettings pds;
    //pds = new SRSPrintDestinationSettings();
    //pds.printMediumType(SRSPrintMediumType::LACScreen); // Lasernet Fax is used as destination - as we need just to create PDF without actual distributing it
    //pds.lacDestinationSettings().destTypes4Print(LACDestinationSettings::SRSPrintMediumType2LACDestTypes4Print(pds.printMediumType()));
    //pds.lacDestinationSettings().forceReRun(NoYes::Yes);     // This flag uses Force rerun of the report. Set NoYes::No if you want already existing Arhice to be picked up
    //pds.lacDestinationSettings().skipDelivery(true);         // This flag skips file distribution in Lasernet server
    //pds.lacDestinationSettings().returnFileData(NoYes::Yes); // This flag makes process to run in Synchronous mode, and waits for results from Lasernet server

    runQueryReport.parmPrintSettings().unpack(LACReportRunResult_DispContext::getSRSPrintDestinationSettings().pack());

    // Optional - Show/Hide dialog
    runQueryReport.parmShowDialog(false);
    // Using Disposable context object that is wrapping actual Posting process, that has Report print inside
    // This conext object can be accessed from the inner process and used to put required information. In this case Result of PDF file
    using (LACReportRunResult_DispContext reportRunResultContext = new LACReportRunResult_DispContext())
    {
        runQueryReport.startOperation();;

        // result to be filled in with all infomration (PDF binaries) in deeper process
        while (reportRunResultContext.moveNextLACResult())
        {
            if (reportRunResultContext.currentLACResult().dataPDF())
            {
                str                     resultReportName = reportRunResultContext.currentLACResult().parmReportName();
                Filename                fileName = resultReportName + '_' + reportRunResultContext.currentLACResult().firstDestination().outputFile(LACFileType::PDF).fileNameOnly();

                System.IO.MemoryStream  fileData = Binary::constructFromContainer(reportRunResultContext.currentLACResult().dataPDF()).getMemoryStream();
                File::SendFileToUser(fileData, fileName);
                fileGenerated = true;
            }
        }
    }
    if (!fileGenerated)
    {
        warning('No files were generated or retrieved.');
    }

}

/// <summary>
///
/// </summary>
public void clicked()
{
    LACReportName   reportName = 'LACTutorialODataReport';
    str             rangeOnDataSource = 'quotes', rangeOnField = 'name', rangeValue = 'AFUser_Quote333';
    LACReport       report = LACReport::find(reportName);
    if (!report)
    {
        throw error(strFmt('OData report %1 must be created and have data source named %2 with field %3 available for range', reportName, rangeOnDataSource, rangeOnField));
    }
    if (!report.Active)
    {
        throw error(strFmt('Report %1 must be active', reportName));
    }
    Args args = new Args();
    args.record(report);
    LACRunController controller = LACRunController::newFromArgs(args, false);
    LACRunClassDataContract classDataContract = controller.parmLACRunDataContract() as LACRunClassDataContract;
    // Optional - set odata ranges ranges
    Map rangesMap = classDataContract.parmRanges(); // auto initializes map
    Array dataSourceRangeArray = rangesMap.exists(rangeOnDataSource)?rangesMap.lookup(rangeOnDataSource):new Array(Types::Class);

    // Data sources array on report
    //   Array dataSourcesArray = classDataContract.dataSourceArray();
    //   Each element of type LACDataSource (could be LACDataSource_Table or LACDataSource_OdataEntity
    // Data source fields array
    //   LACDataSource dataSourceObject = dataSourcesArray.value(1);
    //   Array fieldsArray = dataSourceObject.fields()
    //   Each fields array element of type LACDataSourceField
    // Data source ranges - all ranges saved in one map. Map structure [DataSourceName->Array(LACDataSourceRange)]
    LACDataSourceRange range = LACDataSourceRange::newRange(rangeOnDataSource, rangeOnField);
    range.value = rangeValue;
    dataSourceRangeArray.value(dataSourceRangeArray.lastIndex()+1, range);
    rangesMap.insert(rangeOnDataSource, dataSourceRangeArray);

    // Optional - where to print
    if (!destinationSettings)
    {
        destinationSettings = new SRSPrintDestinationSettings();
    }
    controller.parmPrintSettings().unpack(destinationSettings.pack());

    // Optional - Show/Hide dialog
    controller.parmShowDialog(true);
    controller.startOperation();
}

/// <summary>
///  
/// </summary>
public void clicked()
{
    LACReportName         reportName = 'LACTutorialProjTableExplode';
    LACReport             report;

    super();
    report = LACReport::find(reportName);
    if (report.RecId)
    {
        info(strFmt('Report \'%1\' already exists. It will be recreated.', reportName));
    }
    setPrefix(strFmt('Creating report \'%1\'', reportName));
    LACUtils::importLACFromResource(resourceStr(LACTutorialProjTableExplode_Report));
    report = LACReport::find(reportName);
    if (report.RecId)
    {
        Args a = new Args();
        MenuFunction mf = new MenuFunction(menuItemDisplayStr(LACReport), MenuItemType::Display);
        a.record(report);
        a.caller(element);
        mf.run(a);
        info(strFmt('Report %1 has been created and is ready to be used', reportName));
    }
}

